using System.Collections;
using UnityEngine;
using UnityEngine.UI;
namespace DiwaliGameplay {
public class FireworksGame : VenueGame {
 public GrabbableItem rocket,fountain,spinner,plunger;
 public Transform rocketSocket,fountainSocket,spinnerSocket,rocketPlatform,lift,spinnerPivot;
 public ParticleSystem rocketEffect,fountainEffect,spinnerEffect;
 public int stage,aimPreset,speedPreset;
 public Slider timingBar;
 public Vector3 panelPosition;public Quaternion panelRotation;
 public Vector3 rocketStagingPosition;
 public bool rocketLoaded,fountainLoaded,spinnerLoaded,raised;
 public float phase,holdProgress;
 public Vector3 liftHome,plungerHome;
 public Transform plungerFrame;
 public Quaternion rocketHome,spinnerHome;
 public float travel=.18f;
 public bool TimingReady=>true;
 VenuePanel panel;
 Button beginButton,launchButton,finaleButton;
 Slider aimSlider,liftSlider,speedSlider;
 bool rocketHandled,fountainHandled,spinnerHandled,triggerHeld,handBaselineSet,wasDown;
 float handStartY,liftAmount,spinSpeed=45;
 Quaternion plungerRotation;
 Vector3 rocketStaging;
 protected override void Awake(){base.Awake();if(rocket){rocketStaging=rocketStagingPosition!=Vector3.zero?rocketStagingPosition:rocket.transform.position;var delta=Vector3.ProjectOnPlane(rocketStaging-rocketSocket.position,Vector3.up);if(delta.magnitude<.7f){var venue=GameObjectUtility.FindExact("Fireworks - Native PBR");var side=venue?venue.right:Vector3.right;rocketStaging=rocketSocket.position+side*.95f;rocketStaging.y=rocketSocket.position.y;}}if(plunger){plungerFrame=plunger.transform.parent?plunger.transform.parent:transform;plungerHome=plungerFrame.InverseTransformPoint(plunger.transform.position);plungerRotation=plunger.transform.rotation;plunger.grab.trackPosition=false;plunger.grab.trackRotation=false;plunger.grab.trackScale=false;plunger.grab.activated.AddListener(_=>triggerHeld=true);plunger.grab.deactivated.AddListener(_=>triggerHeld=false);plunger.grab.selectEntered.AddListener(e=>{handStartY=plungerFrame.InverseTransformPoint(e.interactorObject.GetAttachTransform(plunger.grab).position).y;handBaselineSet=true;});plunger.grab.selectExited.AddListener(_=>{triggerHeld=false;handBaselineSet=false;});}}
 void Start(){howToPlay="No timing challenge. Each station has three steps: LOAD, ADJUST, ACTIVATE.\n1. Begin, then grip the rocket from its staging tray and release it near the rocket support.\n2. Move the Aim slider to rotate the platform, then select Launch Rocket. The plunger is an alternative launch control.\n3. Load the fountain, adjust its Lift slider, then select Start Fountain.\n4. Load the spinner, adjust its Speed slider, then select Start Spinner.\n5. Select Finale. Current controls follow the active station. Restart restores the props.";
  var venue=GameObjectUtility.FindExact("Fireworks - Native PBR");if(venue){var board=GameObjectUtility.FindUnder(venue,"board");if(board){var b=GameObjectUtility.BoundsOf(board);var toward=Vector3.ProjectOnPlane(venue.position-b.center,Vector3.up).normalized;float front=Mathf.Abs(toward.x)*b.extents.x+Mathf.Abs(toward.z)*b.extents.z;panelPosition=b.center+toward*(front+.04f);panelRotation=Quaternion.LookRotation(-toward,Vector3.up);}}
  panel=VenuePanel.Create(this,panelPosition,panelRotation,"FIREWORKS • LOAD / ADJUST / LAUNCH");panel.SetPhysicalSize(.82f,1.05f);beginButton=panel.AddButton("Begin Light Show",BeginGame);aimSlider=panel.AddSlider("Aim rocket platform",.5f,AdjustAim);liftSlider=panel.AddSlider("Fountain lift height",.25f,AdjustLift);speedSlider=panel.AddSlider("Spinner speed",.25f,AdjustSpeed);foreach(var s in new[]{aimSlider,liftSlider,speedSlider}){s.minValue=0;s.maxValue=1;}launchButton=panel.AddButton("Activate current firework",()=>Press(0));finaleButton=panel.AddButton("Finale",Finale);rocket.transform.position=rocketStaging;RefreshControls();}
 void PlacePanel(){if(!panel)return;Vector3 target;if(!begun||stage>=3){target=panelPosition;}else{var socket=stage==0?rocketSocket:stage==1?fountainSocket:spinnerSocket;var venue=GameObjectUtility.FindExact("Fireworks - Native PBR");var front=venue?-venue.forward:Vector3.back;target=socket.position+front*.65f+Vector3.Cross(Vector3.up,front)*1.2f+Vector3.up*.4f;target.y=Mathf.Clamp(target.y,1.1f,1.65f);}panel.transform.position=target;if(Camera.main)panel.FaceToward(Camera.main.transform.position);}
 void RefreshControls(){if(!panel)return;beginButton.gameObject.SetActive(!begun);panel.SetControlVisible(aimSlider,begun&&stage==0&&rocketLoaded);panel.SetControlVisible(liftSlider,begun&&stage==1&&fountainLoaded);panel.SetControlVisible(speedSlider,begun&&stage==2&&spinnerLoaded);launchButton.gameObject.SetActive(begun&&!completed&&(stage==0&&rocketLoaded&&aimPreset==1||stage==1&&fountainLoaded&&raised||stage==2&&spinnerLoaded&&speedPreset==1));launchButton.GetComponentInChildren<Text>().text=stage==0?"Launch Rocket":stage==1?"Start Fountain":"Start Spinner";finaleButton.gameObject.SetActive(begun&&stage==3&&!completed);}
 public override void BeginGame(){ResetGame();base.BeginGame();Credit("begin");status="ROCKET 1/3: grip the rocket from the staging tray and release it onto its support.";PlacePanel();}
 public bool Load(GrabbableItem item){if(!begun||completed||item.IsHeld)return false;if(stage==0&&item==rocket&&!rocketLoaded){rocketLoaded=true;rocket.SnapTo(rocketSocket,true);Credit("rocket-load");status="ROCKET 2/3: move the Aim slider. The platform rotates visibly.";}else if(stage==1&&item==fountain&&!fountainLoaded){fountainLoaded=true;fountain.SnapTo(fountainSocket,true);Credit("fountain-load");status="FOUNTAIN 2/3: move the Lift slider to choose a height.";}else if(stage==2&&item==spinner&&!spinnerLoaded){spinnerLoaded=true;spinner.SnapTo(spinnerSocket,true);Credit("spinner-load");status="SPINNER 2/3: move the Speed slider to choose its speed.";}else return false;PlacePanel();RefreshControls();return true;}
 public void AdjustAim(float value){if(!begun||stage!=0||!rocketLoaded)return;aimPreset=1;rocketPlatform.localRotation=rocketHome*Quaternion.Euler(0,Mathf.Lerp(-35,35,value),0);Credit("aim");status="ROCKET 3/3: select Launch Rocket, or press the grabbed plunger. No timing requirement.";RefreshControls();}
 public void AdjustLift(float value){if(!begun||stage!=1||!fountainLoaded)return;raised=true;liftAmount=Mathf.Lerp(.05f,.35f,value);Credit("raise");status="FOUNTAIN 3/3: select Start Fountain, or press the plunger.";RefreshControls();}
 public void AdjustSpeed(float value){if(!begun||stage!=2||!spinnerLoaded)return;speedPreset=1;spinSpeed=Mathf.Lerp(25,150,value);Credit("spin");status="SPINNER 3/3: select Start Spinner, or press the plunger.";RefreshControls();}
 public void Aim()=>AdjustAim(.65f);public void Raise()=>AdjustLift(.65f);public void Spin()=>AdjustSpeed(.65f);
 public bool Press(float ignoredTiming){if(!begun||completed)return false;if(stage==0&&rocketLoaded&&aimPreset==1){Credit("rocket-fire");stage=1;StartCoroutine(RocketFlight());status="FOUNTAIN 1/3: load the fountain onto the lift.";}else if(stage==1&&fountainLoaded&&raised){Credit("fountain-hold");holdProgress=2;fountainEffect.Play();StartCoroutine(StopFountain());stage=2;status="SPINNER 1/3: load the spinner onto its support.";}else if(stage==2&&spinnerLoaded&&speedPreset==1){Credit("spinner-fire");spinnerEffect.Play();stage=3;status="All three displays are ready. Select Finale.";}else{status="Load the current firework and adjust its slider before activating it.";return false;}PlacePanel();RefreshControls();return true;}
 public void Finale(){if(!begun||stage!=3||completed)return;if(!FestivalJourney.ReadyForFinale){status="Prepare Rangoli, sweets, Diya and festival lights first. "+FestivalJourney.Summary;return;}Credit("finale");rocketEffect.Play();fountainEffect.Play();spinnerEffect.Play();StartCoroutine(StopFountain());Complete("Light show complete — all 11 actions finished!");RefreshControls();}
 IEnumerator StopFountain(){yield return new WaitForSeconds(3);fountainEffect.Stop();}
 IEnumerator RocketFlight(){var start=rocket.transform.position;float t=0;while(t<1.2f){t+=Time.deltaTime;rocket.transform.position=start+Vector3.up*t*5;yield return null;}rocketEffect.transform.position=rocket.transform.position;rocketEffect.Play();rocket.SnapTo(rocketSocket,true);}
 public override void Tick(){RefreshControls();if(!begun||completed)return;rocketHandled|=rocket.IsHeld;fountainHandled|=fountain.IsHeld;spinnerHandled|=spinner.IsHeld;if(rocketHandled&&!rocketLoaded&&!rocket.IsHeld&&Vector3.Distance(rocket.transform.position,rocketSocket.position)<.65f)Load(rocket);if(fountainHandled&&!fountainLoaded&&!fountain.IsHeld&&Vector3.Distance(fountain.transform.position,fountainSocket.position)<.65f)Load(fountain);if(spinnerHandled&&!spinnerLoaded&&!spinner.IsHeld&&Vector3.Distance(spinner.transform.position,spinnerSocket.position)<.65f)Load(spinner);lift.localPosition=Vector3.MoveTowards(lift.localPosition,liftHome+Vector3.up*liftAmount,Time.deltaTime*.5f);if(spinnerLoaded&&speedPreset==1)spinnerPivot.Rotate(Vector3.right,spinSpeed*Time.deltaTime,Space.Self);float down=0;if(plunger.IsHeld&&handBaselineSet&&plunger.grab.interactorsSelecting.Count>0){var hand=plunger.grab.interactorsSelecting[0].GetAttachTransform(plunger.grab);down=Mathf.Clamp(handStartY-plungerFrame.InverseTransformPoint(hand.position).y,0,travel);}if(plunger.IsHeld&&triggerHeld)down=travel;plunger.transform.SetPositionAndRotation(plungerFrame.TransformPoint(plungerHome+Vector3.down*down),plungerRotation);bool pressed=plunger.IsHeld&&down>=travel*.45f;if(pressed&&!wasDown)Press(0);wasDown=pressed;}
 public override void ResetGame(){StopAllCoroutines();base.ResetGame();stage=aimPreset=speedPreset=0;rocketLoaded=fountainLoaded=spinnerLoaded=raised=rocketHandled=fountainHandled=spinnerHandled=triggerHeld=handBaselineSet=wasDown=false;phase=holdProgress=liftAmount=0;foreach(var item in new[]{rocket,fountain,spinner,plunger})if(item)item.ResetItem();if(rocket)rocket.transform.position=rocketStaging;if(lift)lift.localPosition=liftHome;if(rocketPlatform)rocketPlatform.localRotation=rocketHome;if(spinnerPivot)spinnerPivot.localRotation=spinnerHome;foreach(var p in new[]{rocketEffect,fountainEffect,spinnerEffect})if(p)p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);PlacePanel();}
}
}
